/* src/content/policy.js */

const NO_SPONSORSHIP = /(?:no|cannot|can't|will not|won't|unable to)\s+(?:provide|offer|sponsor|support).{0,40}(?:visa|sponsorship)|(?:visa|sponsorship).{0,40}(?:not\s+(?:available|offered)|unavailable)/i;

function parseAgeHours(raw) {
  if (!raw) return null;
  const value = raw.trim().toLowerCase();
  const match = value.match(/(\d+)\s*(minute|hour|day|week)s?\s+ago/);
  if (!match) return null;
  const units = { minute: 1 / 60, hour: 1, day: 24, week: 168 };
  return Number(match[1]) * units[match[2]];
}

function includesAny(haystack, needles) {
  const normalized = String(haystack || "").toLowerCase();
  return needles.some((item) => normalized.includes(item.toLowerCase()));
}

function assessJob(job, profile, policy) {
  const reasons = [];
  const age = parseAgeHours(job.postedText);
  if (age !== null && age > policy.maxAgeHours) return result("skip", null, ["Too old"], job);
  if (age === null) reasons.push("Date unknown");

  const body = [job.title, job.description].filter(Boolean).join(" ");
  if (profile.needsSponsorship && NO_SPONSORSHIP.test(body)) return result("skip", null, ["No sponsorship"], job);
  if (profile.needsSponsorship && !job.description) reasons.push("Open description");

  if (policy.allowedLocations.length && job.location && !includesAny(job.location, policy.allowedLocations)) {
    return result("skip", null, ["Location filter"], job);
  }
  if (policy.allowedLocations.length && !job.location) reasons.push("Location unknown");

  const title = String(job.title || "");
  const roleTermSets = profile.targetRoles.map((role) => role.toLowerCase().split(/\W+/).filter((term) => term.length > 2));
  const titleTerms = roleTermSets.flat();
  const roleMatchScores = roleTermSets.map((terms) => terms.length ? terms.filter((term) => title.toLowerCase().includes(term)).length / terms.length : 0);
  const roleMatches = titleTerms.filter((term) => title.toLowerCase().includes(term)).length;
  // Require only one meaningful title term locally. Exact role compatibility
  // belongs to Jev once the full description has been extracted.
  if (profile.targetRoles.length && titleTerms.length && roleMatches === 0) {
    return result("skip", null, ["Wrong role"], job);
  }
  // Cards without a full description still get a provisional title-level
  // rating. Opening the job later replaces this result with Jev's assessment.
  const skillHits = profile.skills.filter((skill) => includesAny(body, [skill])).length;
  const roleHit = profile.targetRoles.length ? Math.max(...roleMatchScores, 0) : 0.5;
  const skillScore = !job.description || !profile.skills.length ? 0.5 : skillHits / profile.skills.length;
  const fit = Math.round((10 * (0.6 * roleHit + 0.4 * skillScore)) * 10) / 10;
  if (fit < policy.minimumFit) return result("skip", fit, ["Low match"], job);
  if (!job.description) reasons.push("Provisional");
  return result("keep", fit, reasons, job, !job.description);
}

function applyJevAssessment(local, classifier, policy) {
  if (local.decision === "skip") return local;
  if (!classifier?.adequateEvidence) return { ...local, decision: "check", fit: null, reasons: ["Uncertain"] };
  if (classifier.sponsorship === "unavailable") return { ...local, decision: "skip", fit: null, reasons: ["No sponsorship"] };
  const fit = Number(classifier.fit);
  if (!Number.isFinite(fit) || fit < 0 || fit > 10) return { ...local, decision: "check", fit: null, reasons: ["Invalid classification"] };
  if (classifier.confidence < 0.55) return { ...local, decision: "check", fit, reasons: ["Uncertain"] };
  return { ...local, fit, decision: fit >= policy.minimumFit ? "keep" : "skip", reasons: fit >= policy.minimumFit ? [] : ["Low match"] };
}

function result(decision, fit, reasons, job, provisional = false) {
  return { key: jobKey(job), decision, fit, reasons, provisional, job };
}

/* src/content/content-script.js */

function badge(result) {
  const node = document.createElement("job-sieve-badge");
  node.className = "job-sieve-badge";
  const colors = { keep: "#00875a", skip: "#dc2626", check: "#f59e0b" };
  node.setAttribute("aria-label", result.decision === "keep" ? "Job Sieve: keep" : result.decision === "skip" ? "Job Sieve: skip" : "Job Sieve: check");
  node.title = node.getAttribute("aria-label");
  node.style.cssText = "all:initial !important;position:absolute !important;display:block !important;box-sizing:border-box !important;left:0 !important;top:0 !important;bottom:0 !important;width:3px !important;height:auto !important;margin:0 !important;padding:0 !important;border:0 !important;border-radius:2px 0 0 2px !important;background:" + colors[result.decision] + " !important;box-shadow:0 0 0 1px rgba(15,23,42,.2),1px 0 2px rgba(15,23,42,.18) !important;line-height:0 !important;z-index:2 !important;";
  const root = node.attachShadow({ mode: "closed" });
  root.append(document.createElement("span"));
  return node;
}

function attachBadges(results, hideSkipped) {
  document.querySelectorAll(".job-sieve-badge").forEach((node) => node.remove());
  document.querySelectorAll("[data-job-sieve-hidden]").forEach((node) => { node.hidden = false; node.removeAttribute("data-job-sieve-hidden"); });
  for (const result of results) {
    const candidateLinks = [...document.querySelectorAll("a[href]")].filter((link) => link.href === result.job.url);
    const target = candidateLinks[0]?.closest("li, .job-card-container, .posting") || document.querySelector("[data-job-sieve-key='" + CSS.escape(result.key) + "']");
    if (!target) continue;
    if (getComputedStyle(target).position === "static") target.style.position = "relative";
    target.append(badge(result));
    if (hideSkipped && result.decision === "skip") { target.hidden = true; target.dataset.jobSieveHidden = "true"; }
  }
}

async function scan() {
  const settings = await chrome.runtime.sendMessage({ type: "GET_SETTINGS" });
  const jobs = enrichWithOpenDescription(extractLoadedJobs());
  const localResults = jobs.map((job) => assessJob(job, settings.profile, settings.policy));
  const results = await Promise.all(localResults.map(async (local) => {
    if (local.decision === "skip" || !local.job.description) return local;
    const response = await chrome.runtime.sendMessage({ type: "CLASSIFY_JOB", job: local.job });
    return response.ok ? applyJevAssessment(local, response.result, settings.policy) : { ...local, decision: "check", fit: null, reasons: ["Classifier unavailable"] };
  }));
  attachBadges(results, settings.policy.hideSkipped);
  await chrome.runtime.sendMessage({ type: "PAGE_RESULTS", results });
  return results;
}

chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
  if (message.type === "SCAN_PAGE") { scan().then((results) => sendResponse({ ok: true, results })); return true; }
  if (message.type === "RESTORE_SKIPPED") { attachBadges([], false); sendResponse({ ok: true }); }
  return undefined;
});
